                ffi.Pointer<ffi.Void>,
                ffi.Int32,
                ffi.Pointer<ffi.Void>,
              )
            >
          >('g_action_map_add_action_entries')
          .asFunction<
            void Function(
              ffi.Pointer<ffi.Void>,
              ffi.Pointer<ffi.Void>,
              int,
              ffi.Pointer<ffi.Void>,
            )
          >();
  void addActionEntries(
    ffi.Pointer<ffi.Void> entries,
    int nEntries,
    ffi.Pointer<ffi.Void> userData,
  ) {
    _gActionMapAddActionEntries(this.handle, entries, nEntries, userData);
  }

  /// Looks up the action with the name @action_name in @action_map.
  ///
  /// If no such action exists, returns `NULL`.
  static final _gActionMapLookupAction =
      gioLookup<
            ffi.NativeFunction<
              ffi.Pointer<ffi.Void> Function(
                ffi.Pointer<ffi.Void>,
                ffi.Pointer<Utf8>,
              )
            >
          >('g_action_map_lookup_action')
          .asFunction<
            ffi.Pointer<ffi.Void> Function(
              ffi.Pointer<ffi.Void>,
              ffi.Pointer<Utf8>,
            )
          >();
  GAction? lookupAction(String actionName) {
    return withNativeString(actionName, (nativeActionName) {
      return (_gActionMapLookupAction(
                this.handle,
                nativeActionName.cast<Utf8>(),
              )) ==
              ffi.nullptr
          ? null
          : GAction.fromPointer(
              _gActionMapLookupAction(
                this.handle,
                nativeActionName.cast<Utf8>(),
              ),
            );
    });
  }

  /// Removes the named action from the action map.
  ///
  /// If no action of this name is in the map then nothing happens.
  static final _gActionMapRemoveAction =
      gioLookup<
            ffi.NativeFunction<
              ffi.Void Function(ffi.Pointer<ffi.Void>, ffi.Pointer<Utf8>)
            >
          >('g_action_map_remove_action')
          .asFunction<
            void Function(ffi.Pointer<ffi.Void>, ffi.Pointer<Utf8>)
          >();
  void removeAction(String actionName) {
    withNativeString(actionName, (nativeActionName) {
      _gActionMapRemoveAction(this.handle, nativeActionName.cast<Utf8>());
    });
  }

  /// Remove actions from a [iface@Gio.ActionMap]. This is meant as the reverse of
  /// [method@Gio.ActionMap.add_action_entries].
  ///
  ///
  /// ```c
  /// static const GActionEntry entries[] = {
  /// { "quit",         activate_quit              },
  /// { "print-string", activate_print_string, "s" }
  /// };
  ///
  /// void
  /// add_actions (GActionMap *map)
  /// {
  /// g_action_map_add_action_entries (map, entries, G_N_ELEMENTS (entries), NULL);
  /// }
  ///
  /// void
  /// remove_actions (GActionMap *map)
  /// {
  /// g_action_map_remove_action_entries (map, entries, G_N_ELEMENTS (entries));
  /// }
  /// ```
  static final _gActionMapRemoveActionEntries =
      gioLookup<
            ffi.NativeFunction<
              ffi.Void Function(
                ffi.Pointer<ffi.Void>,
                ffi.Pointer<ffi.Void>,
                ffi.Int32,
              )
            >
          >('g_action_map_remove_action_entries')
          .asFunction<
            void Function(ffi.Pointer<ffi.Void>, ffi.Pointer<ffi.Void>, int)
          >();
  void removeActionEntries(ffi.Pointer<ffi.Void> entries, int nEntries) {
    _gActionMapRemoveActionEntries(this.handle, entries, nEntries);
  }
}
